1	<!DOCTYPE html>
2	<html lang="en">
3	<head>
4	  <meta charset="UTF-8">
5	  <meta name="viewport" content="width=device-width, initial-scale=1.0">
6	  <title>Pulsing Circle</title>
7	  <style>
8	    * {
9	      margin: 0;
10	      padding: 0;
11	      box-sizing: border-box;
12	    }
13	    body {
14	      width: 100vw;
15	      height: 100vh;
16	      display: flex;
17	      justify-content: center;
18	      align-items: center;
19	      background: radial-gradient(circle at center, #1a1a2e 0%, #0d0d17 100%);
20	      overflow: hidden;
21	    }
22	    svg {
23	      width: min(400px, 80vmin);
24	      height: min(400px, 80vmin);
25	      overflow: visible;
26	    }
27	    .core {
28	      animation: pulse 2.5s ease-in-out infinite;
29	      transform-origin: 200px 200px;
30	      filter: url(#glow);
31	    }
32	    .ring {
33	      fill: none;
34	      stroke: #8ec5ff;
35	      stroke-width: 2;
36	      transform-origin: 200px 200px;
37	      animation: ripple 2.5s ease-out infinite;
38	    }
39	    @keyframes pulse {
40	      0%, 100% {
41	        transform: scale(1);
42	        opacity: 0.9;
43	      }
44	      50% {
45	        transform: scale(1.05);
46	        opacity: 1;
47	      }
48	    }
49	    @keyframes ripple {
50	      0% {
51	        transform: scale(1);
52	        opacity: 0.6;
53	      }
54	      100% {
55	        transform: scale(1.35);
56	        opacity: 0;
57	      }
58	    }
59	    @media (prefers-reduced-motion: reduce) {
60	      .core, .ring {
61	        animation: none;
62	      }
63	    }
64	  </style>
65	</head>
66	<body>
67	  <svg id="ae683f770" viewBox="0 0 400 400">
68	    <defs>
69	      <radialGradient id="circleGradient" cx="35%" cy="35%" r="65%">
70	        <stop offset="0%" stop-color="#8ec5ff"/>
71	        <stop offset="55%" stop-color="#4a7dd9"/>
72	        <stop offset="100%" stop-color="#1f3a75"/>
73	      </radialGradient>
74	      <filter id="glow" x="-50%" y="-50%" width="200%" height="200%">
75	        <feGaussianBlur in="SourceGraphic" stdDeviation="8" result="blur"/>
76	        <feMerge>
77	          <feMergeNode in="blur"/>
78	          <feMergeNode in="SourceGraphic"/>
79	        </feMerge>
80	      </filter>
81	    </defs>
82	    <circle class="ring" cx="200" cy="200" r="180"/>
83	    <circle class="core" cx="200" cy="200" r="180" fill="url(#circleGradient)"/>
84	  </svg>
85	</body>
86	</html>
